// Atividade guiada (#/aula/atividade) — design V3Atividade (Aula kit): the teacher picks the sites,
// the window and the first question; the result is a shareable link to #/aula. No accounts, no storage.
// Source of truth: this .tsx file (Preact). atividade.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, type ComponentChildren, type VNode } from "../../vendor/preact/preact.module.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, mount } from "../../ds/ui.js";
import { QUESTIONS } from "./aula.js";
import { loadComparison, SitePickers } from "./comparar.js";
import { ContextBar, setQuery } from "./common.js";

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const { sc, entries } = await loadComparison(ctx);
  const q = Math.min(QUESTIONS.length, Math.max(1, Number(ctx.query.q) || 1));
  const shareQuery = { ...ctx.query, r: null, q: String(q) };
  const link = location.href.split("#")[0] + buildHash("/aula", shareQuery);

  const step = (n: number, title: string, ...body: ComponentChildren[]): VNode => <section class="solid card">
    <div class="row"><span class="mk" aria-hidden="true">{String(n)}</span><h2 class="h-card">{title}</h2></div>{body}</section>;

  mount(outlet, <>
    <div class="page-head"><div><p class="lbl-s">Kit Aula</p><h1 data-route-title="">Montar atividade guiada</h1></div></div>
    <div class="split">
      <div class="stack">
        {step(1, "Escolha os locais e a janela", <SitePickers ctx={ctx} sc={sc} entries={entries} />, <ContextBar ctx={ctx} sc={sc} siteSelect={false} />)}
        {step(2, "Escolha a primeira pergunta", <div class="stack" role="radiogroup" aria-label="Primeira pergunta">{QUESTIONS.map((Q, i) =>
          <button type="button" class="wpill" role="radio" aria-checked={i + 1 === q} aria-pressed={i + 1 === q}
            onClick={() => setQuery(ctx, { q: String(i + 1) })}><span class="letter">{String(i + 1)}</span>{Q.q}</button>)}</div>)}
        {step(3, "Compartilhe com a turma",
          <label class="fld share"><span class="lbl-s">Link da atividade</span><input type="text" readOnly defaultValue={link} onFocus={e => (e.target as HTMLInputElement).select()} /></label>,
          <div class="row wrap"><button type="button" class="btnA" onClick={async e => {
            const b = e.currentTarget as HTMLButtonElement;
            try { await navigator.clipboard.writeText(link); b.textContent = "Link copiado"; } catch { b.textContent = "Copie o link ao lado"; }
          }}>Copiar link</button><a class="btnL" href={buildHash("/aula", shareQuery)}>Apresentar no projetor →</a></div>,
          <p class="t3 small">QR code: N/D nesta versão (sem biblioteca externa). O link abre a mesma pergunta, com a resposta escondida.</p>)}
      </div>
      <div class="stack">
        <section class="glass card"><span class="lbl-s">Prévia do aluno</span>
          <p class="title-l">{QUESTIONS[q - 1].q}</p>
          <p class="t2">{entries.map(e => e.name.replace(/\s*\(.*\)$/, "")).join(" · ")}</p>
          <p class="row t3 small"><Badge kind="est" />Dados LOLA + SPICE, prévios. Resposta só aparece quando o professor revela.</p></section>
        <details class="notes glass card" open><summary>Notas do professor</summary>
          <ul class="t2">
            <li>Peça palpites antes de revelar; depois peça para explicar o papel do relevo.</li>
            <li>Visibilidade é geometria: não inclui antena, rádio, painel ou bateria.</li>
            <li>Os locais são centros de catálogo, não pontos de pouso certificados.</li>
          </ul></details>
      </div>
    </div>
  </>);
}
